struct LoroSubscriptionHandle *loro_ephemeral_subscribe(const struct LoroEphemeralHandle *e, ErrSlot err);

/**
 * Queues `[bytes update]` for every local change, to send to other peers.
 */
struct LoroSubscriptionHandle *loro_ephemeral_subscribe_local_updates(const struct LoroEphemeralHandle *e, ErrSlot err);

/**
 * Tracks local changes of `doc` for undo/redo. Remote changes are never
 * undone, but undo steps are transformed so they still apply on top of them.
 */
struct LoroUndoHandle *loro_undo_new(const struct LoroDocHandle *d, ErrSlot err);

void loro_undo_free(struct LoroUndoHandle *u);

/**
 * Returns 1 if a step was undone.
 */
int32_t loro_undo_undo(const struct LoroUndoHandle *u, ErrSlot err);

/**
 * Returns 1 if a step was redone.
 */
int32_t loro_undo_redo(const struct LoroUndoHandle *u, ErrSlot err);

/**
 * `which`: 0 can undo, 1 can redo, 2 undo count, 3 redo count, 4 is paused.
 */
uint32_t loro_undo_query(const struct LoroUndoHandle *u, uint32_t which, ErrSlot err);

void loro_undo_record_new_checkpoint(const struct LoroUndoHandle *u, ErrSlot err);

void loro_undo_set_max_undo_steps(const struct LoroUndoHandle *u, uint32_t steps, ErrSlot err);

/**
 * Local changes closer together than `ms` are merged into one undo step.
 */
void loro_undo_set_merge_interval(const struct LoroUndoHandle *u, double ms, ErrSlot err);

/**
 * Commits whose origin starts with `prefix` are not recorded.
 */
void loro_undo_add_exclude_origin_prefix(const struct LoroUndoHandle *u, const uint8_t *prefix_ptr, uint32_t prefix_len, ErrSlot err);

/**
 * `op`: 0 clear, 1 group start, 2 group end, 3 pause, 4 resume.
 */
void loro_undo_control(const struct LoroUndoHandle *u, uint32_t op, ErrSlot err);

/**
 * Allocates `len` zeroed bytes that the caller fills with input data.
 */
uint8_t *loro_alloc(uint32_t len);

/**
 * Frees memory returned by [`loro_alloc`]; `len` must match.
 */
void loro_dealloc(uint8_t *ptr, uint32_t len);

/**
 * Frees an owned output buffer (`[u32 len][payload]`).
 */
void loro_buf_free(uint8_t *ptr);

#endif  /* LORO_CRDT_FFI_H */
